def solve(inputs: dict) -> float:
    M = inputs['matrix']
    n = inputs['exponent']
    mod = inputs['modulus']

    # Convert to list of lists if needed
    if not isinstance(M, list):
        M = M.tolist()

    size = len(M)

    # Helper function to multiply two matrices mod p
    def matrix_mult(A, B, mod):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for k in range(size):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Fast exponentiation
    def matrix_pow(M, n, mod):
        if n == 1:
            return [row[:] for row in M]  # Copy M

        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]  # Identity
        base = [row[:] for row in M]

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result = matrix_pow(M, n, mod)

    # Sum all entries
    total = sum(sum(row) for row in result) % mod
    return float(total)

